import re
from docx import Document

with open('/root/employee_data.json') as f:
    data = json.load(f)

doc = Document('/root/offer_letter_template.docx')

include_relocation = data.get('RELOCATION_PACKAGE', '').strip().lower() == 'yes'

if_start = '{{IF_RELOCATION}}'
if_end = '{{END_IF_RELOCATION}}'


def process_conditional(text):
    if if_start not in text and if_end not in text:
        return text
    pattern = re.compile(re.escape(if_start) + r'(.*?)' + re.escape(if_end), re.DOTALL)
    if include_relocation:
        return pattern.sub(lambda m: m.group(1), text)
    return pattern.sub('', text)


def replace_in_paragraph(para):
    text = para.text
    new_text = process_conditional(text)
    for match in re.finditer(r'\{\{([A-Z_]+)\}\}', new_text):
        key = match.group(1)
        if key in data:
            new_text = new_text.replace(match.group(0), str(data[key]))
    if new_text != text:
        runs = para.runs
        if runs:
            runs[0].text = new_text
            for run in runs[1:]:
                run.text = ''


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                replace_in_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


for para in doc.paragraphs:
    replace_in_paragraph(para)

for table in doc.tables:
    process_table(table)

for section in doc.sections:
    for para in section.header.paragraphs:
        replace_in_paragraph(para)
    for para in section.footer.paragraphs:
        replace_in_paragraph(para)

doc.save('/root/offer_letter_filled.docx')
print('Saved.')
